insert into style(key,name,era,grp,description,principles,when_to_use) values('schwartz','Eugene Schwartz','1950-80','dr','Mestre dos estágios de consciência e sofisticação do mercado. Não cria desejo — canaliza o desejo de massa que já existe.','["Estágios de consciência do prospect","Sofisticação do mercado","Canalizar o desejo, não criar","Headline entra na conversa da mente"]'::jsonb,'Definir o ângulo e a headline conforme o momento do público.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('halbert','Gary Halbert','1970-2000','dr','O mais lido dos copywriters de resposta direta. Direto, conversacional e movido a história. Acreditava no “mercado faminto”.','["Starving crowd > copy","Tom de pessoa para pessoa","Histórias que prendem","A-pile / B-pile"]'::jsonb,'Cartas de venda e e-mails que soam pessoais.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('hopkins','Claude Hopkins','1900-30','dr','Pioneiro da “publicidade científica”. Reason-why, prova e especificidade. Testava tudo.','["Reason-why copy","Especificidade vence generalidade","Demonstre o mecanismo","Teste e meça"]'::jsonb,'Copy que precisa provar e demonstrar.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('kennedy','Dan Kennedy','1980-2020','dr','Resposta direta sem rodeios. Oferta irresistível, urgência, garantia e CTA forte.','["Oferta irresistível","Urgência e escassez","Garantia que remove o risco","Message-Market-Media"]'::jsonb,'Ofertas, promoções e fechamento de infoproduto.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('sugarman','Joe Sugarman','1970-2000','dr','Criador do conceito de “slippery slide”: cada frase existe para fazer você ler a próxima.','["Slippery slide","Primeira frase curtíssima","Gatilhos psicológicos","Fluxo de leitura contínuo"]'::jsonb,'Long-form que precisa de fluidez e engajamento.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('collier','Robert Collier','1920-50','dr','Mestre das cartas de venda. Ensinou a “entrar na conversa que já existe na mente do prospect”.','["Entrar na conversa interna","Conexão contextual","Emoção antes da razão","Carta como diálogo"]'::jsonb,'E-mail/carta com forte conexão de contexto.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('caples','John Caples','1920-90','dr','Autoridade em headlines testadas. Apelo a interesse próprio, notícia e curiosidade.','["Headlines testadas","Self-interest em primeiro lugar","Notícia e curiosidade","Manchete que promete recompensa"]'::jsonb,'Criar e testar manchetes.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('bencivenga','Gary Bencivenga','1970-2010','dr','Considerado um dos maiores copywriters vivos. Prega que prova vence persuasão — o segredo é credibilidade.','["Prova acima de promessa","Credibilidade vence ceticismo","Benefício + evidência","Teste rigoroso"]'::jsonb,'Converter público cético com provas.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('carlton','John Carlton','1980-2020','dr','O “copywriter mais implacável”. Famoso pelo anúncio do golfista de uma perna só — gancho + história que vende.','["Gancho irresistível","História que vende","Linguagem de rua","Oferta clara"]'::jsonb,'Ganchos fortes e cartas de venda diretas.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('makepeace','Clayton Makepeace','1980-2010','dr','Um dos maiores nomes de copy financeira e de saúde. Copy movida a emoção e grandes promessas com prova.','["Emoção em primeiro lugar","Grande promessa","Prova robusta","Ritmo de leitura"]'::jsonb,'Ofertas de alta conversão em saúde e finanças.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('schwab','Victor Schwab','1930-60','dr','Autor de “How to Write a Good Advertisement”. Sintetizou os 5 fundamentos do anúncio que vende.','["Atrair atenção","Mostrar a vantagem","Provar","Persuadir","Pedir a ação"]'::jsonb,'Estrutura clássica e testada de anúncio.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('sackheim','Maxwell Sackheim','1920-60','dr','Criador do Book-of-the-Month Club e do clássico “Do You Make These Mistakes in English?”. Mestre da curiosidade.','["Headline de curiosidade","Oferta de continuidade","Persistência (regra dos 7)","Resposta mensurável"]'::jsonb,'Headlines de curiosidade e ofertas recorrentes.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('jekennedy','John E. Kennedy','1900-10','dr','Definiu a publicidade como “salesmanship in print” (um vendedor no papel) — base de toda a resposta direta.','["Anúncio = vendedor","Razão para comprar (reason-why)","Foco na venda, não no entretenimento"]'::jsonb,'Fundamento: tratar a copy como um vendedor.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('stone','Bob Stone','1960-90','dr','Lenda do marketing direto. Criou a fórmula de carta em 7 passos, começando pelo maior benefício.','["Liderar com o maior benefício","Expandir o benefício","Provar","Dizer o que se perde","Pedir ação"]'::jsonb,'Mala direta e estrutura de carta de vendas.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('bird','Drayton Bird','1960-2020','dr','Maior nome do marketing direto britânico, discípulo de Ogilvy. Clareza obsessiva e foco em vender.','["Clareza acima de tudo","Relevância para o leitor","Testar e medir","Vender, não impressionar"]'::jsonb,'Marketing direto claro e persuasivo.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('lasker','Albert Lasker','1900-40','dr','Pai da publicidade moderna (Lord & Thomas). Popularizou o “reason-why” como motor da venda.','["Reason-why","Salesmanship in print","Estratégia antes da arte"]'::jsonb,'Fundamentar a venda por argumento.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('ogilvy','David Ogilvy','1950-90','brand','O “pai da publicidade”. Pesquisa, fatos e elegância. Headlines fortes e copy longa que respeita o leitor.','["Pesquisa antes de escrever","“O consumidor não é idiota”","Headline carrega 80% do peso","Fatos e benefícios concretos"]'::jsonb,'Marca premium e anúncios baseados em benefícios.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('bernbach','Bill Bernbach','1950-80','brand','Pai da revolução criativa (DDB). Provou que criatividade vende — “Think Small” (VW) e “We try harder” (Avis).','["A grande ideia","Criatividade a serviço da venda","Respeito à inteligência do público","Execução impecável"]'::jsonb,'Conceito criativo disruptivo de marca.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('burnett','Leo Burnett','1930-70','brand','Criou ícones eternos: Marlboro Man, Tigre Tony, Gigante Verde. Buscava o “drama inerente” do produto.','["Drama inerente do produto","Personagens-ícone","Emoção arquetípica","Simplicidade"]'::jsonb,'Construir ícones e símbolos de marca.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('reeves','Rosser Reeves','1940-60','brand','Criador da USP (Proposta Única de Venda). “Melts in your mouth, not in your hand” (M&M’s).','["Uma proposta única","Benefício que o concorrente não oferece","Repetição / martelo","Foco na conversão"]'::jsonb,'Achar e martelar a proposta única.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('rubicam','Raymond Rubicam','1920-40','brand','Cofundador da Young & Rubicam. Uniu impacto criativo a pesquisa e qualidade.','["Impacto (resista ao familiar)","Pesquisa + criação","Qualidade e originalidade"]'::jsonb,'Marca de impacto sustentada por pesquisa.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('wells','Mary Wells Lawrence','1960-90','brand','Primeira mulher CEO de empresa na bolsa de NY. Campanhas ousadas: Braniff, Alka-Seltzer, “I ♥ NY”.','["Ousadia memorável","Experiência de marca","Humor e charme","Coragem criativa"]'::jsonb,'Campanhas ousadas e inesquecíveis.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('lois','George Lois','1960-2000','brand','Mestre da “big idea” provocadora. Capas da Esquire e o icônico “I want my MTV”.','["Big idea provocadora","Choque cultural","Coragem","Ideia antes da execução"]'::jsonb,'Ideia ousada que vira conversa cultural.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('abbott','David Abbott','1970-2000','brand','O maior redator britânico de long copy. Inteligência e elegância (The Economist, Volvo).','["Long copy que prende","Inteligência e elegância","Verdade sobre o produto","Respeito ao leitor"]'::jsonb,'Long copy elegante e inteligente.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('hegarty','John Hegarty','1980-2010','brand','Cofundador da BBH. “When the world zigs, zag” — diferenciação como religião (Levi’s, Audi).','["Diferenciação radical","A ideia em uma frase","Marca com atitude","Menos é mais"]'::jsonb,'Posicionar a marca contra a manada.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('wieden','Dan Wieden','1980-2010','brand','Cofundador da Wieden+Kennedy. Criou o “Just Do It” da Nike — marca como atitude e cultura.','["Marca-atitude","Voz cultural autêntica","Coragem para arriscar","Verdade emocional"]'::jsonb,'Manifestos e voz de marca.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('clow','Lee Clow','1980-2010','brand','Mente por trás do “1984” e do “Think Different” da Apple. Manifestos que definem marcas.','["Manifesto de marca","Simplicidade icônica","Emoção + design","Pensar diferente"]'::jsonb,'Manifestos e grandes lançamentos.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('gossage','Howard Gossage','1950-60','brand','O “Sócrates de São Francisco”. Anúncios que dialogam e respeitam o leitor, com humor e interação.','["Conversa, não monólogo","Respeito e humor","Engajar, não interromper"]'::jsonb,'Anúncios que dialogam e engajam.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('resor','Helen L. Resor','1910-40','brand','Pioneira entre as redatoras (JWT). Criou o apelo emocional/sensorial: “A skin you love to touch”.','["Apelo emocional e sensorial","Aspiração","Voz autêntica"]'::jsonb,'Apelo emocional e aspiracional.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('wiebe','Joanna Wiebe','2010-hoje','modern','Fundadora da Copyhackers e mãe do “conversion copywriting”. Copy nasce da voz do cliente.','["Voz do cliente (VoC)","Copy baseada em dados","Clareza > esperteza","Teste de conversão"]'::jsonb,'Copy de conversão digital baseada em pesquisa.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('georgi','Stefan Georgi','2015-hoje','modern','Um dos copywriters modernos que mais faturam. Criador do método RMBC para VSLs e cartas.','["Método RMBC","Mecanismo único","Lead forte","Prova e história"]'::jsonb,'VSLs e cartas de venda modernas.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('benson','Jon Benson','2000-hoje','modern','Criador da VSL (Video Sales Letter). Estruturou o roteiro de vídeo que vende.','["Roteiro de VSL","Loop aberto","Mecanismo único","CTA repetido"]'::jsonb,'Roteiros de vídeo de vendas.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('brunson','Russell Brunson','2010-hoje','modern','Fundador do ClickFunnels. Mestre em funis e na “Epiphany Bridge” — vender pela história de origem.','["Epiphany Bridge","Funil de valor","História de origem","Oferta escada"]'::jsonb,'Funis e narrativa de origem.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('redwards','Ray Edwards','2000-hoje','modern','Criador do framework PASTOR — uma das estruturas de copy mais usadas hoje.','["PASTOR","Problema → Oferta → Resposta","História e transformação","Clareza ética"]'::jsonb,'Estruturar copy completa (PASTOR).') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('kern','Frank Kern','2000-hoje','modern','Lenda do marketing digital. “Results in Advance” — entregar valor antes de vender.','["Valor antecipado","Storytelling pessoal","Naturalidade","Relacionamento"]'::jsonb,'Lançamentos e copy de marketing digital.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('riestrout','Al Ries & Jack Trout','1970-2000','strategy','Autores de “Posicionamento”. A batalha não é no produto, é na mente — seja dono de uma palavra.','["Posicionamento","Ser dono de uma palavra","Ser o primeiro (ou criar categoria)","Foco"]'::jsonb,'Definir o posicionamento na mente do cliente.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('cialdini','Robert Cialdini','1980-hoje','strategy','Autor de “As Armas da Persuasão”. Sistematizou os princípios que levam ao “sim”.','["Reciprocidade","Escassez","Autoridade","Prova social","Compromisso e coerência","Afinidade"]'::jsonb,'Aplicar gatilhos de persuasão éticos.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('godin','Seth Godin','2000-hoje','strategy','Autor de “Vaca Roxa” e do marketing de permissão. Seja notável ou seja invisível.','["Seja notável (remarkable)","Marketing de permissão","Fale para a tribo","Conte uma história verdadeira"]'::jsonb,'Tornar a ideia/produto notável.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('sharp','Byron Sharp','2010-hoje','strategy','Autor de “How Brands Grow”. Crescimento por disponibilidade mental e física, baseado em evidência.','["Alcance amplo","Disponibilidade mental e física","Ativos distintivos","Penetração > lealdade"]'::jsonb,'Crescimento de marca baseado em evidência.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('olivetto','Washington Olivetto','1980-2010','br','Maior nome da propaganda brasileira (W/Brasil). Emoção e brasilidade: “Primeiro Sutiã” (Valisère) e o Garoto Bombril.','["Emoção brasileira","Conceito memorável","Humor e afeto","Storytelling de marca"]'::jsonb,'Campanhas emocionais com cara de Brasil.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('nizan','Nizan Guanaes','1980-2010','br','Força criativa do Grupo ABC / DM9. Campanhas de grande impacto e ambição.','["Grande impacto","Ambição criativa","Marca com causa","Energia"]'::jsonb,'Campanhas de marca de alto impacto.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('jribeiro','Júlio Ribeiro','1970-2000','br','Fundador da Talent e referência em planejamento e posicionamento no Brasil (“Fazer Acontecer”).','["Planejamento estratégico","Posicionamento","Foco no consumidor","Disciplina"]'::jsonb,'Estratégia e posicionamento à brasileira.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('duailibi','Roberto Duailibi','1960-2000','br','Um dos pais da propaganda moderna brasileira (o “D” da DPZ). Criação clássica e elegante.','["Criação clássica","Conceito + estética","Marca institucional","Bom gosto"]'::jsonb,'Criação clássica e institucional.') on conflict(key) do nothing;
insert into style(key,name,era,grp,description,principles,when_to_use) values('serpa','Marcello Serpa','1990-2010','br','Diretor de criação da AlmapBBDO, multipremiado em Cannes. Conceito visual forte com copy enxuta.','["Conceito visual","Menos texto, mais ideia","Impacto gráfico","Elegância"]'::jsonb,'Conceito visual potente com copy mínima.') on conflict(key) do nothing;
insert into framework(key,name,structure) values('AIDA','AIDA','Atenção → Interesse → Desejo → Ação') on conflict(key) do nothing;
insert into framework(key,name,structure) values('AIDCA (AIDA + Convicção)','AIDCA (AIDA + Convicção)','Atenção → Interesse → Desejo → Convicção → Ação') on conflict(key) do nothing;
insert into framework(key,name,structure) values('PAS (Problema-Agitação-Solução)','PAS (Problema-Agitação-Solução)','Problema → Agitação → Solução') on conflict(key) do nothing;
insert into framework(key,name,structure) values('PASTOR','PASTOR','Problema → Amplificação → História/Solução → Transformação (depoimentos) → Oferta → Resposta (CTA)') on conflict(key) do nothing;
insert into framework(key,name,structure) values('BAB (Antes-Depois-Ponte)','BAB (Antes-Depois-Ponte)','Estado Antes → Estado Depois → Ponte (o produto)') on conflict(key) do nothing;
insert into framework(key,name,structure) values('4 Ps','4 Ps','Promessa → Imagem (Picture) → Prova → Empurrão (Push)') on conflict(key) do nothing;
insert into framework(key,name,structure) values('PPPP (Picture-Promise-Prove-Push)','PPPP (Picture-Promise-Prove-Push)','Imagem → Promessa → Prova → Empurrão') on conflict(key) do nothing;
insert into framework(key,name,structure) values('FAB (Feature-Advantage-Benefit)','FAB (Feature-Advantage-Benefit)','Característica → Vantagem → Benefício') on conflict(key) do nothing;
insert into framework(key,name,structure) values('Star-Story-Solution','Star-Story-Solution','Estrela (protagonista) → História → Solução') on conflict(key) do nothing;
insert into framework(key,name,structure) values('QUEST','QUEST','Qualificar → Entender → Educar → Estimular → Transição (CTA)') on conflict(key) do nothing;
insert into framework(key,name,structure) values('ACCA','ACCA','Consciência → Compreensão → Convicção → Ação') on conflict(key) do nothing;
insert into framework(key,name,structure) values('4 U''s (headline)','4 U''s (headline)','Útil → Urgente → Único → Ultraespecífico') on conflict(key) do nothing;
insert into framework(key,name,structure) values('USP (Proposta Única de Venda)','USP (Proposta Única de Venda)','Proposta única → Benefício exclusivo → Martelo (repetição)') on conflict(key) do nothing;
insert into framework(key,name,structure) values('Slippery Slide (Sugarman)','Slippery Slide (Sugarman)','Primeira frase curtíssima → cada frase puxa a próxima → fechamento') on conflict(key) do nothing;
insert into framework(key,name,structure) values('Epiphany Bridge (Brunson)','Epiphany Bridge (Brunson)','História de origem → epifania → nova oportunidade → oferta') on conflict(key) do nothing;
insert into framework(key,name,structure) values('5 Estágios de Consciência (Schwartz)','5 Estágios de Consciência (Schwartz)','Inconsciente → consciente do problema → da solução → do produto → totalmente consciente') on conflict(key) do nothing;
insert into framework(key,name,structure) values('Fórmula de 7 passos (Bob Stone)','Fórmula de 7 passos (Bob Stone)','Maior benefício → expandir → o que recebe → provar → o que perde se não agir → resumir → pedir ação') on conflict(key) do nothing;
