insert into piece_type(key,category_key,name,description,structure,default_framework,default_style,length_hint) values('ecom:desc-loja','ecom','Descrição do e-commerce / Sobre a loja','Texto institucional da home/sobre que apresenta a loja.','História → missão → diferenciais → convite','Star-Story-Solution','olivetto','120-220 palavras') on conflict(key) do nothing;
insert into piece_type(key,category_key,name,description,structure,default_framework,default_style,length_hint) values('ecom:desc-categoria','ecom','Descrição de categoria','Texto da página de categoria, com apelo e SEO.','Intro da categoria → variedade/benefícios → SEO natural → CTA navegar','AIDA','ogilvy','60-120 palavras') on conflict(key) do nothing;
insert into piece_type(key,category_key,name,description,structure,default_framework,default_style,length_hint) values('ecom:desc-prod-curta','ecom','Descrição de produto (curta)','Descrição objetiva para a vitrine do produto.','Gancho de benefício → 2-3 características → fecho','FAB (Feature-Advantage-Benefit)','ogilvy','40-80 palavras') on conflict(key) do nothing;
insert into piece_type(key,category_key,name,description,structure,default_framework,default_style,length_hint) values('ecom:desc-prod-longa','ecom','Descrição de produto (detalhada)','Descrição completa, persuasiva e com prova.','Abertura sensorial → benefícios → especificações (reason-why) → prova → CTA','FAB (Feature-Advantage-Benefit)','hopkins','120-250 palavras') on conflict(key) do nothing;
insert into piece_type(key,category_key,name,description,structure,default_framework,default_style,length_hint) values('ecom:sobre-produto','ecom','Sobre o produto (storytelling)','Narrativa que conecta o produto à vida do cliente.','História/origem → problema que resolve → uso no dia a dia','Star-Story-Solution','halbert','80-150 palavras') on conflict(key) do nothing;
insert into piece_type(key,category_key,name,description,structure,default_framework,default_style,length_hint) values('ecom:bullets','ecom','Bullets de benefícios','Lista de bullets persuasivos (fascinations).','Cada bullet = benefício + curiosidade','4 U''s (headline)','sugarman','4-7 bullets') on conflict(key) do nothing;
insert into piece_type(key,category_key,name,description,structure,default_framework,default_style,length_hint) values('ecom:titulo-prod','ecom','Título de produto (otimizado)','Título de vitrine claro e com keyword.','Produto + atributo único + benefício/keyword','USP (Proposta Única de Venda)','reeves','até 60 caracteres') on conflict(key) do nothing;
